// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Veritabanı ve SQL sorguları (metinle) (zor).
const ozComputing10Zor = <(String, String, List<String>, String)>[
  ('Bir sınıfta 30 öğrenciden 12\'si başarılı. PostgreSQL\'de SELECT 12 / 30 * 100; sorgusu hangi değeri verir?', '0', ['40', '40.0', '4'], '12 / 30 tamsayı bölmesiyle 0 olur, 0 × 100 de 0\'dır. Doğru yüzde için önce 100 ile çarpmak ya da kesirli türe çevirmek gerekir.'),
  ('PostgreSQL\'de SELECT CAST(9.7 AS INTEGER); sorgusunun sonucu hangisidir?', '10', ['9', '9.7', 'Hata'], 'PostgreSQL ondalık değeri tamsayıya çevirirken yuvarlar; 9,7 en yakın tamsayı olan 10\'a döner.'),
  ('SELECT ROUND(1234.5, -2); sorgusu PostgreSQL\'de hangi sonucu verir?', '1200', ['1234.50', '1300', '1235'], 'Negatif basamak sayısı virgülün soluna yuvarlar; -2 en yakın yüzlüğe yuvarlamaktır.'),
  ('PostgreSQL\'de SELECT -7 % 3; sorgusunun sonucu hangisidir?', '-1', ['2', '1', '-2'], 'PostgreSQL\'de kalanın işareti bölünen sayının işaretini izler: -7 = 3 × (-2) + (-1).'),
  ('UTF-8 kodlu bir PostgreSQL veritabanında \'Çağrı\' metni için LENGTH ve OCTET_LENGTH sırasıyla hangi değerleri verir?', '5 ve 8', ['5 ve 5', '8 ve 5', '10 ve 5'], 'LENGTH karakter sayısını (5), OCTET_LENGTH bayt sayısını verir; Ç, ğ ve ı ikişer bayt tuttuğu için toplam 8 bayttır.'),
  ('Ortanca adı (orta_ad) birçok kişide NULL olan bir tablonun tam adı ad || \' \' || orta_ad || \' \' || soyad ile üretmek hangi soruna yol açar?', 'Ortanca adı olmayan kişilerin tam adı NULL çıkar', ['Ortanca adı olmayanlarda adla soyad arasında fazladan boşluk kalır', 'Sorgu sözdizimi hatası verir', 'Ortanca adı olanlar listeden çıkar'], '|| işleci tek bir NULL ile bütün sonucu NULL yapar; COALESCE ya da CONCAT_WS ile çözülür.'),
  ('Bir LIKE kalıbında yüzde işaretinin kendisini (örneğin \'%50\' indirimini) aramak için ne yapılır?', 'ESCAPE ile kaçış karakteri tanımlanır', ['Kalıp çift tırnakla yazılır', 'Yüzde işareti iki kez arka arkaya yazılır', 'LIKE yerine BETWEEN kullanılır'], 'Örneğin LIKE \'%50!%%\' ESCAPE \'!\' kalıbında \'!%\' gerçek yüzde işareti olarak okunur.'),
  ('Telefon sütunundaki \'0532\' ile başlayıp toplam 11 haneli numaraları bulan koşul hangisidir?', 'telefon LIKE \'0532_______\'', ['telefon LIKE \'0532%\'', 'telefon LIKE \'%0532\'', 'telefon LIKE \'0532_\''], '\'0532\' dört karakterdir; toplam 11 olması için ardından tam 7 alt çizgi gerekir.'),
  ('PostgreSQL\'de DATE \'2024-01-31\' + INTERVAL \'1 month\' ifadesi hangi tarihi verir?', '2024-02-29', ['2024-03-02', '2024-02-28', '2024-03-01'], 'PostgreSQL ay eklerken gün ayın son gününü aşarsa o ayın son gününe çeker; 2024 şubatı 29 gündür.'),
  ('PostgreSQL\'de EXTRACT(DOW FROM tarih) pazar günü için hangi değeri döndürür?', '0', ['1', '7', '6'], 'DOW alanı haftanın gününü pazar 0, cumartesi 6 olacak biçimde verir.'),
  ('Zaman damgası (TIMESTAMP) türündeki kayit_zamani sütununda WHERE kayit_zamani BETWEEN \'2024-05-01\' AND \'2024-05-31\' koşulu hangi kayıtları kaçırır?', '31 Mayıs\'ta gece yarısından sonra yapılan kayıtları', ['1 Mayıs\'ta gece yarısından sonra yapılan kayıtları', 'Yalnız saat bilgisi olmayan kayıtları', 'Mayıs ayının hafta sonu kayıtlarını'], '\'2024-05-31\' metni 31 Mayıs 00:00:00 anına çevrilir; o günün daha geç saatleri aralığın dışında kalır.'),
  ('CASE renk WHEN NULL THEN \'yok\' ELSE \'var\' END ifadesi renk NULL olan bir satırda ne üretir?', '\'var\'', ['\'yok\'', 'NULL', 'Hata'], 'Basit CASE eşitlikle karşılaştırır; renk = NULL karşılaştırması TRUE olmadığı için ELSE dalına düşer. Doğrusu CASE WHEN renk IS NULL biçimidir.'),
  ('Bir CASE ifadesinin THEN dallarından biri metin, diğeri sayı döndürürse çoğu VTYS\'de ne olur?', 'Tür uyuşmazlığı hatası ya da zorunlu dönüşüm gerekir', ['Her satır kendi türüyle, karışık biçimde döndürülür', 'Sayı otomatik olarak NULL yapılır', 'CASE yalnız ilk dalın türünü dikkate alıp kalanları siler'], 'Bir ifadenin tek bir sonuç türü olmalıdır; dallar ortak bir türe çevrilemiyorsa sorgu hata verir.'),
  ('a ve b sütunlarının ikisi de NULL olduğunda a IS DISTINCT FROM b ifadesi ne döndürür?', 'FALSE', ['TRUE', 'NULL', 'UNKNOWN ve satırı siler'], 'IS DISTINCT FROM NULL\'ları eşit sayar; iki NULL birbirinden farklı değildir, sonuç FALSE olur.'),
  ('PostgreSQL\'de GREATEST(3, NULL, 8) ifadesi hangi değeri döndürür?', '8', ['NULL', '3', 'Hata'], 'PostgreSQL\'de GREATEST NULL argümanları yok sayar ve kalanların en büyüğünü verir; bu davranış bazı VTYS\'lerde farklıdır.'),
  ('PostgreSQL\'de SELECT DISTINCT sehir FROM Musteri ORDER BY kayit_tarihi; sorgusu neden hata verir?', 'DISTINCT ile sıralama sütununun seçim listesinde olması gerekir', ['ORDER BY tarih türündeki sütunlarla hiçbir koşulda kullanılamaz', 'DISTINCT yalnız sayısal sütunlarda çalışır', 'Bir sorguda DISTINCT ile ORDER BY birlikte kullanılamaz'], 'Aynı şehrin birçok kayıt tarihi olabileceği için hangi tarihe göre sıralanacağı belirsizdir; standart bu yüzden sütunun seçilmesini ister.'),
  ('Puanları 95, 90, 90, 85 olan bir listede ORDER BY puan DESC FETCH FIRST 2 ROWS WITH TIES kaç satır döndürür?', '3', ['2', '4', '1'], 'WITH TIES, son alınan satırla aynı sıralama değerine sahip satırları da ekler; ikinci satırdaki 90 ile eşit olan üçüncü satır da gelir.'),
  ('Maaşlar 9000, 9000, 7000, 5000 iken \'ikinci en yüksek farklı maaşı\' bulmak için ORDER BY maas DESC LIMIT 1 OFFSET 1 yazan sorgu hangi değeri verir?', '9000', ['7000', '5000', 'Sorgu boş sonuç döndürür'], 'Tekrarlanan 9000 değeri iki satır tuttuğu için ikinci satır yine 9000\'dir; doğru sonuç için önce DISTINCT uygulanmalıdır.'),
  ('Bir renk sütununun değerleri \'mavi\', NULL, NULL ve \'kırmızı\' iken kümeleme fonksiyonu COUNT(DISTINCT renk) hangi sonucu verir?', '2', ['3', '4', 'NULL değerle birlikte 3'], 'Kümeleme fonksiyonları NULL değerleri sayıma katmaz; yalnız \'mavi\' ve \'kırmızı\' sayılır.'),
  ('PostgreSQL\'e özgü SELECT DISTINCT ON (sinif) ad, puan FROM Ogrenci ORDER BY sinif, puan DESC; sorgusu ne döndürür?', 'Her sınıfın en yüksek puanlı öğrencisini', ['Her sınıftan puanı tekrar etmeyen bütün öğrencileri', 'Yalnız tek öğrencili sınıfları', 'Bütün öğrencileri sınıfa göre gruplanmış sırada'], 'DISTINCT ON her sınıf değeri için sıralamadaki ilk satırı tutar; puan azalan sıralandığı için ilk satır en yüksek puandır.'),
  ('WHERE id NOT IN (3, 7, NULL) koşulu, id değeri 5 olan bir satır için ne sonuç verir?', 'UNKNOWN; satır döndürülmez', ['TRUE; satır döndürülür', 'FALSE; ancak satır yine döndürülür', 'Sorgu sözdizimi hatası verir'], '5 <> NULL karşılaştırması UNKNOWN olduğundan VE ile bağlanan bütün koşul TRUE olamaz.'),
  ('Musteri tablosundan, Siparis tablosundaki musteri_no listesinde yer almayan müşteriler NOT IN ile aranıyor. Siparis.musteri_no sütununda bir NULL bulunursa sonuç ne olur?', 'Hiç satır dönmez', ['Bütün müşteriler döner', 'Yalnız NULL\'a karşılık gelen müşteri döner', 'Sorgu NULL satırı atlayıp doğru çalışır'], 'Listede NULL varsa her NOT IN karşılaştırması UNKNOWN olur; bu yüzden NOT EXISTS daha güvenlidir.'),
  ('x değeri 4 olan bir satırda x IN (4, NULL) ve x değeri 9 olan bir satırda x IN (4, NULL) ifadeleri sırasıyla ne verir?', 'TRUE ve UNKNOWN', ['TRUE ve FALSE', 'UNKNOWN ve UNKNOWN', 'FALSE ve TRUE'], 'Eşleşme bulunursa IN TRUE olur; bulunamazsa ve listede NULL varsa sonuç kesin FALSE değil UNKNOWN\'dur.'),
  ('Sinif ve sube sütunlarının birlikte eşleşmesini isteyen WHERE (sinif, sube) IN (SELECT sinif, sube FROM Program) yazımı ne tür bir karşılaştırmadır?', 'Satır (çoklu sütun) karşılaştırması', ['Kartezyen çarpım', 'İki ayrı IN koşulunun VEYA ile bağlanması', 'Sözdizimi hatası olan bir yazım'], 'Parantezli sütun listesi bir satır değeri oluşturur; iki sütun aynı anda eşleşmelidir.'),
  ('EXISTS (SELECT NULL) ifadesinin sonucu nedir?', 'TRUE', ['NULL', 'FALSE', 'UNKNOWN'], 'Alt sorgu NULL değerli de olsa bir satır döndürür; EXISTS için bu yeterlidir.'),
  ('Alt sorgu hiç satır döndürmezse 5 > ALL (alt sorgu) ve 5 > ANY (alt sorgu) sırasıyla ne verir?', 'TRUE ve FALSE', ['FALSE ve TRUE', 'NULL ve NULL', 'FALSE ve FALSE'], 'Boş kümede \'hepsi için\' koşulu kendiliğinden doğrudur; \'en az biri için\' koşulu ise sağlanamaz.'),
  ('Ders(kod) ve Alir(ogr, kod) tablolarıyla \'bütün dersleri alan öğrencileri\' bulmak için çift NOT EXISTS kullanılır. Bu sorgu hangi ilişkisel cebir işlemine karşılık gelir?', 'Bölme', ['Birleşim', 'Kartezyen çarpım', 'İzdüşüm'], '\'Alamadığı hiçbir ders bulunmayan öğrenci\' mantığı ilişkisel bölmenin SQL karşılığıdır.'),
  ('Bir müşterinin siparişleri 100 ve 300 TL, diğerinin tek siparişi 200 TL\'dir. Müşteri toplamlarının ortalaması ile siparişlerin ortalaması sırasıyla kaçtır?', '300 ve 200', ['200 ve 200', '300 ve 300', '200 ve 300'], 'Müşteri toplamları 400 ve 200, ortalamaları 300\'dür; üç siparişin ortalaması (100 + 300 + 200) / 3 = 200\'dür.'),
  ('Bir sorguda WHERE içinde pencere fonksiyonu sonucuna göre süzme yapılamıyorsa, en yaygın çözüm hangisidir?', 'Hesabı türetilmiş tabloda ya da CTE\'de yapıp dış sorguda süzmek', ['Pencere fonksiyonunu GROUP BY içine taşıyıp her grubu ayrı ayrı sıralamak', 'Koşulu HAVING yerine ORDER BY içine yazmak', 'Pencere fonksiyonunun önüne DISTINCT eklemek'], 'Pencere fonksiyonları WHERE\'den sonra hesaplanır; sonuçları ancak bir dış sorguda koşul olarak kullanılabilir.'),
  ('WITH RECURSIVE k(n) AS (SELECT 1 UNION ALL SELECT n * 2 FROM k WHERE n < 100) SELECT MAX(n) FROM k; sorgusu hangi değeri verir?', '128', ['64', '100', 'Sorgu sonlanmaz'], 'Koşul önceki satıra uygulanır: 64 < 100 olduğu için 128 üretilir, 128 < 100 olmadığından özyineleme durur.'),
  ('Özyinelemeli CTE\'de UNION ALL yerine UNION kullanılmasının döngü içeren bir bağlantı verisine etkisi ne olabilir?', 'Aynı satırlar yeniden üretilmez ve döngü durabilir', ['Çapa bölümü hiç çalışmaz ve sorgu boş döner', 'Sonuçlar ters sırada döner', 'Özyineleme yalnız bir adım ilerler'], 'UNION daha önce üretilmiş satırları atar; yeni satır kalmayınca özyineleme biter.'),
  ('WITH RECURSIVE f(n, deger) AS (SELECT 1, 1 UNION ALL SELECT n + 1, deger * (n + 1) FROM f WHERE n < 5) SELECT MAX(deger) FROM f; sorgusu kaç döndürür?', '120', ['24', '720', 'Hata'], 'Satırlar (1,1), (2,2), (3,6), (4,24), (5,120) olur; bu, 5 faktöriyeldir.'),
  ('Anahtar değerleri 1, 1, 2 olan bir tablo ile 1, 1, 1, 3 olan bir tablo tam dış birleştirmeyle (FULL OUTER JOIN) eşleştirilirse sonuçta kaç satır bulunur?', '8', ['7', '6', '12'], '6 eşleşmeye A\'dan eşsiz 2 ve B\'den eşsiz 3 için birer satır eklenir.'),
  ('Siparis ile Odeme tabloları siparis_no üzerinden birleştirilip SUM(Siparis.tutar) alınıyor. Bir siparişe iki taksit ödemesi bağlıysa bu sipariş toplamı nasıl etkiler?', 'Sipariş tutarı iki kez sayılır ve toplam şişer', ['Toplam değişmez, çünkü SUM yinelenen satırları ayıklar', 'Sipariş toplamdan tamamen çıkar', 'Taksitlerin ortalaması alınır'], 'Birleştirme her ödeme için sipariş satırını tekrarlar; tekrar eden tutar toplamı yanlış biçimde büyütür.'),
  ('Musteri m LEFT JOIN Siparis s ON m.no = s.mno sorgusuna WHERE s.yil = 2023 koşulu eklenirse sonuç nasıl değişir?', '2023 siparişi olmayan müşteriler sonuçtan düşer', ['Bütün müşteriler yine listelenir, yalnız sipariş sütunları süzülür', 'Sorgu hata verir; WHERE dış birleştirmeyle kullanılamaz', 'Siparişi olmayan müşteriler iki kez görünür'], 'NULL dolgulu satırlarda s.yil NULL olduğu için WHERE koşulu sağlanmaz; sonuç fiilen INNER JOIN\'e döner.'),
  ('Bütün müşterileri listeleyip yanlarında yalnız 2023 yılındaki siparişlerini göstermek için yıl koşulu nereye yazılmalıdır?', 'ON m.no = s.mno AND s.yil = 2023', ['WHERE s.yil = 2023 OR s.yil IS NULL', 'HAVING s.yil = 2023', 'ORDER BY s.yil = 2023'], 'Koşul ON içinde olursa yalnız eşleşmeyi kısıtlar; eşi bulunmayan müşteriler NULL sütunlarla korunur.'),
  ('Musteri LEFT JOIN Siparis sonucunda müşteri başına sipariş sayısı alınırken COUNT(*) yerine COUNT(s.id) kullanılmasının nedeni nedir?', 'Siparişi olmayan müşteride COUNT(*) 1, COUNT(s.id) 0 verir', ['COUNT(*) dış birleştirmelerde hiç kullanılamaz, hata üretir', 'COUNT(s.id) daha hızlı çalışır, sonuç aynıdır', 'COUNT(*) yalnız siparişi olan müşterileri sayar'], 'Dış birleştirme eşsiz müşteri için NULL dolgulu bir satır üretir; COUNT(*) bu satırı sayar, COUNT(s.id) NULL\'u saymaz.'),
  ('A LEFT JOIN B ON ... ardından gelen INNER JOIN C ON B.id = C.bid zincirinde, B\'de eşi olmayan A satırlarına ne olur?', 'INNER JOIN aşamasında elenirler', ['Sonuçta NULL sütunlarla korunurlar', 'C tablosunun bütün satırlarıyla eşleşirler', 'Sorgu hata verir'], 'B sütunları NULL olan satırlarda B.id = C.bid koşulu sağlanmaz; iç birleştirme bu satırları atar.'),
  ('MySQL\'in FULL OUTER JOIN desteklemediği sürümlerde aynı sonuç genellikle nasıl elde edilir?', 'LEFT JOIN ile RIGHT JOIN sonuçları UNION ile birleştirilir', ['İki INNER JOIN arka arkaya yazılır ve sonuca DISTINCT eklenir', 'CROSS JOIN sonucuna DISTINCT uygulanır', 'LEFT JOIN\'in sonuna WHERE IS NULL eklenir'], 'İki dış birleştirme iki tarafın eşsizlerini toplar; UNION yinelenen eşleşmeleri ayıklar.'),
  ('4 kişilik bir bölümde a.bolum = b.bolum AND a.id <> b.id koşuluyla yapılan kendisiyle birleştirme o bölüm için kaç satır üretir?', '12', ['6', '16', 'Yalnız 4, her kişi için bir'], 'Her kişi diğer 3 kişiyle sıralı çift oluşturur: 4 × 3 = 12. Her çift iki yönde sayılmaktadır.'),
  ('Aralıklı birleştirmede HarfNotu tablosunda 70–80 ve 80–90 aralıkları sınırları dahil tanımlanmışsa 80 puanlı öğrenci için ne olur?', 'İki harfle eşleşip iki satır üretir', ['Yalnız alt aralıkla eşleşir; üst sınır her zaman dışarıda kalır', 'Eşleşme bulunamaz', 'Sorgu hata verir'], 'BETWEEN iki ucu da kapsar; çakışan sınır değeri her iki aralığın koşulunu sağlar.'),
  ('Urun tablosunda fiyatı kendisinden yüksek olan ürün sayısını her ürün için bulmak amacıyla tablo hangi koşulla kendisiyle birleştirilir?', 'ON b.fiyat > a.fiyat', ['ON b.fiyat = a.fiyat', 'ON b.id = a.id', 'ON b.fiyat < a.fiyat AND b.id = a.id'], 'a satırı, fiyatı kendisinden büyük her b satırıyla eşleşir; bu eşleşmeler sayılarak sıra elde edilir.'),
  ('Bir stok listesinde 7 numaralı ürün üç kez, 8 numaralı ürün bir kez geçiyor; satılanlar listesinde 7 bir kez var. Stok EXCEPT ALL Satilan işlemi kaç satır bırakır?', '3', ['1', '2', 'Yalnız 8 kalır, 1 satır'], 'EXCEPT ALL tekrar sayılarını düşer: üç 7\'den biri çıkar, iki 7 ve 8 kalır. Düz EXCEPT ise yalnız 8\'i bırakırdı.'),
  ('İki sorgunun her ikisinde de NULL değerli bir satır varsa INTERSECT bu satırı sonuca katar mı?', 'Evet; küme işlemleri NULL\'ları birbirinin aynısı sayar', ['Hayır; NULL = NULL koşulu TRUE olmadığı için satır her iki sonuçtan da düşer', 'Yalnız UNION ALL ile birlikte yazılırsa katar', 'Sorgu NULL içerdiği için hata verir'], 'Küme işlemleri eşitliği \'farklı değil\' ölçütüyle değerlendirir; iki NULL aynı satır kabul edilir.'),
  ('Notlar tablosunda (Ali, 40), (Ali, 80), (Ece, 90), (Ece, 50), (Can, 30) var. SELECT ogrenci FROM Notlar WHERE puan >= 45 GROUP BY ogrenci HAVING COUNT(*) >= 1; kaç öğrenci döndürür?', '2', ['3', '1', 'Hiç öğrenci döndürmez'], 'WHERE önce 45 altını atar: Ali 80 ve Ece 90, 50 kalır; Can\'ın satırı kalmadığı için grubu yoktur.'),
  ('GROUP BY içermeyen SELECT COUNT(*) FROM Urun HAVING COUNT(*) > 100; sorgusu 50 satırlı bir tablo üzerinde ne döndürür?', 'Hiç satır döndürmez', ['50', '100', 'Hata verir; HAVING GROUP BY ister'], 'GROUP BY yoksa bütün tablo tek grup sayılır; bu grup koşulu sağlamadığı için elenir.'),
  ('puan sütunu 10, 20 ve NULL değerlerini tutuyorsa AVG(puan) ile SUM(puan) / COUNT(*) sırasıyla hangi değerleri verir?', '15 ve 10', ['10 ve 15', '15 ve 15', 'NULL ve 10'], 'AVG NULL\'u dışlayıp 30 / 2 = 15 hesaplar; COUNT(*) ise 3 satır saydığından 30 / 3 = 10 olur.'),
  ('Hiç satırı olmayan bir tablo üzerinde GROUP BY\'sız SELECT COUNT(*), SUM(fiyat) sorgusu ne döndürür?', 'Tek satır: 0 ve NULL', ['Hiç satır döndürmez', 'Tek satır: 0 ve 0', 'Tek satır: NULL ve NULL'], 'Gruplama yoksa sonuç her zaman tek satırdır; boş kümede COUNT 0, SUM NULL verir.'),
  ('Hiç satırı olmayan bir tablo üzerinde GROUP BY kategori içeren SELECT kategori, COUNT(*) sorgusu kaç satır döndürür?', '0', ['1', 'Kategori sayısı kadar', 'Hata verir'], 'Gruplanacak satır olmadığından hiç grup oluşmaz; sonuç boştur.'),
  ('Siparis tablosunda iptal edilen siparişleri ayrı bir sütunda saymak için PostgreSQL\'in desteklediği standart yazım hangisidir?', 'COUNT(*) FILTER (WHERE durum = \'iptal\')', ['COUNT(*) WHERE durum = \'iptal\'', 'COUNT(durum = \'iptal\' IS TRUE OR NULL) OVER ()', 'FILTER(COUNT(*), durum = \'iptal\')'], 'FILTER yan tümcesi kümeleme fonksiyonunun yalnız koşulu sağlayan satırları işlemesini sağlar.'),
  ('Sınıf A\'da 2 öğrencinin ortalaması 90, sınıf B\'de 8 öğrencinin ortalaması 40\'tır. Sınıf ortalamalarının ortalaması ile bütün öğrencilerin ortalaması sırasıyla kaçtır?', '65 ve 50', ['65 ve 65', '50 ve 65', '50 ve 50'], '(90 + 40) / 2 = 65; öğrenci ağırlıklı ortalama ise (2 × 90 + 8 × 40) / 10 = 50\'dir.'),
  ('İl (2 farklı değer) ve ilçe (her ilde 3 ilçe) sütunlarıyla GROUP BY ROLLUP(il, ilce) kaç satır üretir?', '9', ['6', '8', '12'], '(il, ilçe) için 6, yalnız il için 2 ara toplam ve 1 genel toplam satırı oluşur: 6 + 2 + 1 = 9.'),
  ('GROUP BY CUBE(a, b, c) kaç farklı gruplama kümesi üretir?', '8', ['3', '4', '6'], 'CUBE bütün alt kümeleri üretir; üç sütun için 2³ = 8 gruplama kümesi vardır.'),
  ('GROUP BY GROUPING SETS ((marka), (renk)) ifadesi hangisine denktir?', 'Markaya göre gruplama ile renge göre gruplamanın UNION ALL ile alt alta konması', ['Marka ve renk çiftlerine göre tek bir gruplama', 'Markaya göre gruplamanın ardından her grubun içinde renge göre sıralanarak tek listede verilmesi', 'Marka ve rengin kartezyen çarpımı üzerinde gruplama'], 'Her gruplama kümesi ayrı bir GROUP BY gibi hesaplanır; sonuçlar alt alta birleştirilir.'),
  ('ROLLUP sonucunda ara toplam satırındaki NULL ile verinin kendisindeki NULL\'u ayırt etmek için hangi fonksiyon kullanılır?', 'GROUPING', ['COALESCE', 'NULLIF', 'ISNULL_ROW'], 'GROUPING(sütun), o satırda sütunun ara toplam yüzünden NULL yapıldığını 1 değeriyle bildirir.'),
  ('Her kategoriden tam olarak en pahalı 3 ürünü (eşit fiyatlar olsa da 3\'ten fazla değil) seçmek için alt sorguda hangi fonksiyon kullanılıp dışarıda <= 3 koşulu konmalıdır?', 'ROW_NUMBER() OVER (PARTITION BY kategori ORDER BY fiyat DESC)', ['RANK() OVER (PARTITION BY kategori ORDER BY fiyat DESC)', 'DENSE_RANK() OVER (ORDER BY fiyat DESC)', 'COUNT(*) OVER (PARTITION BY kategori)'], 'RANK ve DENSE_RANK eşitlikte aynı sırayı verip 3\'ten fazla satır bırakabilir; ROW_NUMBER her gruba tam 3 satır bırakır.'),
  ('Değerler 10, 20, 30 iken LAST_VALUE(v) OVER (ORDER BY v) çerçeve belirtilmeden kullanılırsa her satır için hangi sonuç alınır?', 'Her satırın kendi değeri: 10, 20, 30', ['Her satırda 30', 'Her satırda 10', 'İlk satırda NULL, sonra 10 ve 20'], 'Varsayılan çerçeve başlangıçtan geçerli satıra kadardır; son değer o anki satır olur. Tüm grubun sonu için ROWS BETWEEN ... UNBOUNDED FOLLOWING gerekir.'),
  ('Satırlar (gün 1, 5), (gün 2, 10), (gün 2, 20) iken SUM(tutar) OVER (ORDER BY gun) ifadesi ikinci satır için kaç verir?', '35', ['15', '5', '20'], 'Varsayılan çerçeve RANGE\'dir; aynı gün değerine sahip satırlar birlikte dahil edilir: 5 + 10 + 20 = 35.'),
  ('10 öğrencinin puana göre sıralandığı bir sorguda NTILE(4) OVER (ORDER BY puan) gruplara kaçar öğrenci düşürür?', '3, 3, 2, 2', ['2, 2, 3, 3', '2.5 öğrencilik dört eşit grup', '4, 4, 1, 1'], '10 / 4 = 2 kalan 2\'dir; artan 2 öğrenci ilk iki gruba birer birer eklenir.'),
  ('Değerleri 10, 20, 30, 40 olan dört satırda CUME_DIST() OVER (ORDER BY v) 20 değeri için kaç verir?', '0.5', ['0.25', '0.33', '0.75'], 'CUME_DIST, değeri geçerli satırınkine eşit ya da küçük olan satırların oranıdır: 2 / 4 = 0,5.'),
  ('Aynı pencere tanımını birçok fonksiyonda tekrar yazmamak için standart SQL\'de hangi yan tümce kullanılır?', 'WINDOW w AS (PARTITION BY ... ORDER BY ...)', ['WITH w AS (PARTITION BY ... ORDER BY ...)', 'DEFINE w OVER (PARTITION BY ...)', 'GROUP w BY (PARTITION BY ...)'], 'WINDOW yan tümcesi adlandırılmış bir pencere tanımlar; fonksiyonlar OVER w ile buna başvurur.'),
  ('Beş satırlık tek bir INSERT ... VALUES komutunda dördüncü satır NOT NULL kısıtını ihlal ediyorsa PostgreSQL\'de ne olur?', 'Komut hata verir ve beş satırdan biri bile eklenmez', ['İlk üç satır eklenir, kalanlar atlanır', 'Yalnız dördüncü satır atlanır, diğer dört satır eklenir', 'Dördüncü satırdaki boş alan 0 ile doldurulur'], 'Tek bir SQL ifadesi bölünmez biçimde çalışır; bir satırdaki hata bütün ifadeyi geri alır.'),
  ('CREATE TABLE Yedek AS SELECT * FROM Urun; komutuyla oluşturulan tablo için PostgreSQL\'de hangisi doğrudur?', 'Veri kopyalanır ama birincil anahtar ve indeksler kopyalanmaz', ['Yalnız sütun yapısı kopyalanır, satırlar kopyalanmaz', 'Kaynak tablodaki tüm kısıtlar, tetikleyiciler ve indeksler de olduğu gibi kopyalanır', 'Yedek tablo Urun tablosunun canlı bir görünümü olur'], 'CREATE TABLE AS sorgu sonucunu yeni bir tabloya yazar; kısıtların ayrıca tanımlanması gerekir.'),
  ('PostgreSQL\'de a = 1, b = 2 olan bir satırda UPDATE T SET a = b, b = a; çalıştırılırsa sonuç ne olur?', 'a = 2, b = 1', ['a = 2, b = 2', 'a = 1, b = 1', 'a = 1, b = 2'], 'Standart SQL\'de SET içindeki bütün ifadeler satırın eski değerleriyle hesaplanır; böylece değerler yer değiştirir.'),
  ('PostgreSQL\'de Urun tablosundaki fiyatları Guncel(urun_id, yeni_fiyat) tablosundaki değerlere göre güncellemek için hangi yazım kullanılır?', 'UPDATE Urun SET fiyat = g.yeni_fiyat FROM Guncel g WHERE g.urun_id = Urun.id;', ['UPDATE Urun JOIN Guncel SET fiyat = yeni_fiyat;', 'UPDATE Guncel SET Urun.fiyat = Guncel.yeni_fiyat WHERE EXISTS (SELECT 1 FROM Urun);', 'UPDATE Urun SET fiyat = Guncel WHERE id = urun_id;'], 'PostgreSQL UPDATE ... FROM yapısıyla başka tablolardan değer alıp birleştirme koşulunu WHERE\'e yazar.'),
  ('PostgreSQL\'de id\'si zaten var olan bir ürün eklenirken hata yerine fiyatın güncellenmesi için hangi yazım kullanılır?', 'INSERT ... ON CONFLICT (id) DO UPDATE SET fiyat = EXCLUDED.fiyat', ['INSERT ... IF EXISTS UPDATE fiyat', 'INSERT ... WHEN MATCHED THEN UPDATE SET fiyat = NEW.fiyat ELSE INSERT', 'UPDATE ... ON CONFLICT INSERT'], 'ON CONFLICT çakışmayı yakalar; EXCLUDED eklenmek istenen satırın değerlerini temsil eder.'),
  ('CHECK (yas >= 18) kısıtı olan bir sütuna yaş değeri NULL olarak girilirse ne olur?', 'Satır kabul edilir', ['Satır reddedilir', 'Yaş otomatik olarak 18 yapılır', 'Bütün tablo kilitlenir ve işlem bekler'], 'NULL >= 18 karşılaştırması UNKNOWN verir; CHECK yalnız FALSE sonucu reddeder. NULL istenmiyorsa ayrıca NOT NULL gerekir.'),
  ('Satırları bulunan bir tabloya PostgreSQL\'de varsayılan değeri olmayan NOT NULL bir sütun eklenmeye çalışılırsa ne olur?', 'Var olan satırlar NULL içereceği için komut hata verir', ['Sütun eklenir, var olan satırlara 0 yazılır', 'Sütun eklenir ama NOT NULL kısıtı yalnız yeni eklenecek satırlar için geçerli sayılır', 'Var olan satırlar otomatik olarak silinir'], 'Yeni sütun eski satırlarda NULL olacağından kısıt hemen ihlal edilir; DEFAULT verilmesi ya da önce NULL\'a izin verilip doldurulması gerekir.'),
  ('Siparis tablosu Musteri\'ye yabancı anahtarla bağlıyken DROP TABLE Musteri; komutu PostgreSQL\'de ne yapar?', 'Bağımlı nesne bulunduğu için hata verir', ['Musteri ile birlikte Siparis tablosunu da siler', 'Musteri\'yi siler, Siparis\'teki anahtarları NULL yapar', 'Yalnız Musteri\'nin satırlarını siler'], 'Başka nesnelerin bağımlı olduğu tablo ancak DROP TABLE ... CASCADE ile kaldırılabilir; o zaman yabancı anahtar kısıtı da silinir.'),
  ('Otomatik artan numara kullanan bir tabloya ekleme yapan işlem ROLLBACK ile geri alınırsa sonraki başarılı eklemede ne gözlenir?', 'Numara dizisinde boşluk oluşur', ['Geri alınan numara yeniden kullanılır', 'Numaralandırma 1\'den yeniden başlar', 'Ekleme, tablo kilitli olduğu için reddedilir'], 'Diziler (sequence) işlemden bağımsız ilerler; geri alınan işlemin aldığı numara iade edilmez.'),
  ('PostgreSQL\'de toplam sütununun fiyat ile adetten kendiliğinden hesaplanıp saklanması için hangi tanım kullanılır?', 'toplam NUMERIC GENERATED ALWAYS AS (fiyat * adet) STORED', ['toplam NUMERIC DEFAULT', 'toplam NUMERIC CHECK (toplam = fiyat * adet) DEFAULT 0 NOT NULL', 'toplam NUMERIC REFERENCES'], 'Üretilmiş sütun her ekleme ve güncellemede ifadeden yeniden hesaplanır; DEFAULT başka sütunlara başvuramaz.'),
  ('PostgreSQL\'de NUMERIC(5,2) sütununa 12.345 değeri yazılırsa saklanan değer ne olur?', '12.35', ['12.34', '12.345', 'Hata verir'], 'Ölçek 2 olduğu için değer iki ondalık basamağa yuvarlanır.'),
  ('Kuramsal ilişkisel cebirde sehir sütununa izdüşüm (π_sehir) alındığında aynı şehrin birden çok kez geçmesi neden mümkün değildir?', 'İlişkiler küme olduğundan yinelenen demetler kendiliğinden atılır', ['İzdüşüm yalnız birincil anahtar sütunlarına uygulanabilir, şehir sütunu anahtar sayılır', 'Şehir sütunu her zaman benzersizdir', 'İzdüşüm sonuçları her zaman tek satırlık olur'], 'Klasik ilişkisel model kümelere dayanır; SQL ise çoklu küme kullandığı için DISTINCT gerektirir.'),
  ('Alir(ogrenci, ders) ilişkisinde Ali {Mat, Fiz, Kim}, Ece {Mat, Fiz}, Can {Mat, Fiz, Kim, Bio} derslerini alıyor. Dersler = {Mat, Fiz, Kim} ise Alir ÷ Dersler sonucu hangisidir?', 'Ali ve Can', ['Yalnız Ali', 'Ali, Ece ve Can', 'Yalnız Can'], 'Bölme, Dersler kümesindeki bütün dersleri alan öğrencileri verir; Ece Kim almadığı için dışarıda kalır, fazladan ders almak engel değildir.'),
  ('R\'de 6, S\'de 4 demet varsa R − S farkının demet sayısı hangi aralıktadır?', '2 ile 6 arasında', ['0 ile 4 arasında', 'Tam olarak 2', '4 ile 10 arasında'], 'S\'deki demetlerin hepsi R\'de bulunursa 2, hiçbiri bulunmazsa 6 demet kalır.'),
  ('R(A, B, C, D) ilişkisinde F = {AB → C, C → D, D → A} geçerlidir. Aşağıdakilerden hangisi aday anahtar değildir?', 'CD', ['AB', 'BC', 'BD'], 'AB, BC ve BD\'nin kapanışı bütün nitelikleri verir; CD\'nin kapanışı {A, C, D} olup B\'yi içermez.'),
  ('R(A, B, C) ilişkisinin satırları (1, x, p), (1, y, p), (2, x, q) ise aşağıdaki bağımlılıklardan hangisi bu veride sağlanır?', 'A → C', ['A → B', 'B → C', 'B → A ve C → B'], 'A = 1 olan iki satırın C değeri aynıdır (p); A → B\'de 1 iki farklı B\'ye, B → C ve B → A\'da x iki farklı değere gider.'),
  ('R(A, B, C) ilişkisi R1(A, B) ve R2(A, C) olarak ayrıştırılıyor. Ayrıştırmanın kayıpsız olması için hangi bağımlılık yeterlidir?', 'A → B', ['B → C', 'C → B', 'B → A ile B → C'], 'Ortak nitelik A, parçalardan birinin anahtarı olursa birleştirme sahte satır üretmez; A → B, A\'yı R1\'in anahtarı yapar.'),
  ('R(A, B, C, D, E) ilişkisinde F = {A → B, C → D} geçerlidir. Aşağıdakilerden hangisi bir aday anahtardır?', 'ACE', ['AC', 'ABCD', 'AE'], 'A ile B, C ile D bulunur; E hiçbir bağımlılığın sağında yer almadığı için anahtarda olmalıdır. ACE\'nin kapanışı tüm nitelikleri verir ve en küçüktür.'),
  ('Bir okulda her dersin birden çok öğretmeni ve birbirinden bağımsız birden çok ders kitabı vardır; (ders, öğretmen, kitap) tek bir tablo içinde tutuluyor. Bu tasarım hangi normal formu ihlal eder?', 'Dördüncü normal form (4NF)', ['Birinci normal form', 'İkinci normal form', 'Üçüncü normal form (geçişli bağımlılık)'], 'Ders → → öğretmen ve ders → → kitap birbirinden bağımsız çok değerli bağımlılıklardır; tablo 4NF için ikiye ayrılmalıdır.'),
  ('İşlevsel bağımlılık kümesinin gereksiz bağımlılıklardan ve gereksiz sol taraf niteliklerinden arındırılmış eşdeğer biçimine ne ad verilir?', 'En küçük örtü', ['Süper anahtar', 'Kapanış kümesi', 'Kayıpsız birleştirmeli ayrıştırma'], 'En küçük örtü, aynı kapanışı veren en sade bağımlılık kümesidir ve 3NF sentezinde kullanılır.'),
  ('WHERE EXISTS (SELECT 1 FROM Siparis s WHERE s.mno = m.no) koşulu, Siparis.mno NULL içermese de içerse de hangisiyle aynı müşterileri seçer?', 'WHERE m.no IN (SELECT mno FROM Siparis)', ['WHERE m.no NOT IN (SELECT mno FROM Siparis)', 'WHERE m.no = ALL (SELECT mno FROM Siparis)', 'WHERE (SELECT COUNT(*) FROM Siparis) > 0'], 'IN tarafında NULL yalnız eşleşmeyen satırlarda UNKNOWN üretir; eşleşen müşteriler iki yazımda da seçilir. Sorun NOT IN\'e özgüdür.'),
  ('Bir sorgudaki HAVING bolge = \'Ege\' koşulunu WHERE bolge = \'Ege\' olarak taşımak sonucu değiştirir mi? (Sorgu bolge\'ye göre gruplanmaktadır.)', 'Değiştirmez; ama WHERE satırları gruplamadan önce elediği için daha verimlidir', ['Değiştirir; WHERE gruplanmış sütunlarla çalışamaz', 'Değiştirir; HAVING, NULL değerli grupları da tutarken WHERE bunları sorgunun en başında tamamen atar', 'Değiştirmez; ancak WHERE yazımı sözdizimi hatası verir'], 'Koşul gruplama sütunu üzerindeyse iki yer de aynı grupları bırakır; erken süzme daha az satırın gruplanmasını sağlar.'),
  ('SELECT COUNT(*) FROM Ogrenci WHERE puan >= 50; sorgusuyla aynı sayıyı veren yazım hangisidir?', 'SELECT SUM(CASE WHEN puan >= 50 THEN 1 ELSE 0 END) FROM Ogrenci;', ['SELECT COUNT(puan >= 50) FROM Ogrenci GROUP BY puan >= 50 HAVING puan >= 50;', 'SELECT MAX(puan) - 50 FROM Ogrenci;', 'SELECT COUNT(DISTINCT puan) FROM Ogrenci WHERE puan >= 50;'], 'Koşulu sağlayan her satır 1, diğerleri 0 katkı verir. COUNT(puan >= 50) ise FALSE değerleri de sayar.'),
  ('SELECT bolum, COUNT(*) AS sayi FROM Calisan GROUP BY bolum HAVING sayi > 5; sorgusu PostgreSQL\'de neden hata verir?', 'HAVING, SELECT\'teki takma adı tanımaz; COUNT(*) > 5 yazılmalıdır', ['HAVING içinde > işleci kullanılamaz', 'COUNT(*) yerine COUNT(bolum) yazılmalıdır, çünkü yıldız HAVING içinde geçersizdir', 'Takma ad yalnız sayısal sütunlara verilir'], 'HAVING mantıksal sırada SELECT\'ten önce değerlendirilir; PostgreSQL bu yüzden takma adı kabul etmez (bazı VTYS\'ler esnektir).'),
  ('Metin türündeki telefon sütununda indeks varken WHERE telefon = 5321234567 (tırnaksız) yazılırsa bazı VTYS\'lerde ne olabilir?', 'Örtük tür dönüşümü yüzünden indeks kullanılamayabilir', ['Sorgu her zaman daha hızlı çalışır', 'Telefon numaraları otomatik olarak silinir', 'Sütun kalıcı olarak sayı türüne çevrilir ve baştaki sıfırlar silinir'], 'Karşılaştırma için her satırdaki metin sayıya çevrilirse indeksin sırası işe yaramaz; sabit metin olarak yazılmalıdır.'),
  ('PostgreSQL\'de büyük-küçük harf duyarsız aramaları (WHERE LOWER(eposta) = ...) hızlandırmak için ne yapılabilir?', 'LOWER(eposta) üzerinde ifade (fonksiyon) indeksi oluşturmak', ['eposta sütununu sabit uzunluklu CHAR türüne çevirip boşlukları kırpmak', 'Sorguya ORDER BY eposta eklemek', 'eposta sütununa DEFAULT değer vermek'], 'CREATE INDEX ... ON Kullanici (LOWER(eposta)) ile sorgudaki ifadeyle aynı ifade indekslenir.'),
  ('Bir sorgu yalnız (musteri_no, tarih) sütunlarını okuyorsa ve bu iki sütunu içeren bir indeks varsa, tabloya hiç gitmeden yanıt verilebilir. Bu indekse ne ad verilir?', 'Kapsayan indeks', ['Kümelenmiş indeks', 'Seyrek (sparse) birincil indeks', 'Karma (hash) indeksi'], 'Sorgunun ihtiyaç duyduğu bütün sütunlar indekste bulunduğu için yalnız indeks okunur (index-only scan).'),
  ('WHERE durum = \'aktif\' OR sehir = \'Rize\' koşulunda yalnız durum sütununda indeks varsa sorgu genellikle neden tam tabloyu tarar?', 'VEYA\'nın sehir tarafı için yine bütün satırlara bakmak gerekir', ['OR işleci indeksleri her zaman devre dışı bırakır', 'durum sütunu metin olduğu için indeks kullanılamaz', 'OR koşullu sorgular yalnız fiziksel olarak sıralı tutulan tablolarda indeks kullanabilir'], 'Koşulun iki dalından biri indekssiz kalınca o dalın satırlarını bulmak için tarama gerekir; iki sütunda da indeks olsaydı birleştirilebilirdi.'),
  ('PostgreSQL\'de BEGIN; CREATE TABLE Deneme (...); ROLLBACK; dizisinden sonra Deneme tablosu var mıdır?', 'Hayır; PostgreSQL\'de tablo oluşturma da geri alınabilir', ['Evet; DDL komutları her zaman kalıcıdır', 'Evet, ama tablo boştur ve bir sonraki COMMIT\'e kadar salt okunur durumda kalır', 'Hayır, çünkü CREATE TABLE işlem içinde yazılamaz'], 'PostgreSQL DDL komutlarını da işlemsel yürütür; bazı VTYS\'lerde (örneğin MySQL\'de) DDL örtük COMMIT yapar.'),
  ('PostgreSQL\'de bir işlem içinde komutlardan biri hata verdikten sonra yeni bir SELECT gönderilirse ne olur?', 'İşlem iptal durumunda olduğu için ROLLBACK yapılana kadar komutlar reddedilir', ['SELECT normal çalışır, hata unutulur', 'İşlem kendiliğinden COMMIT edilir', 'Hatalı komut otomatik olarak yeniden denenir ve başarılı olursa SELECT çalışır'], 'PostgreSQL hatadan sonra işlemi \'aborted\' durumuna alır; ROLLBACK ya da ROLLBACK TO SAVEPOINT gerekir.'),
  ('İki kayıt noktası tanımlanan bir işlemde (SAVEPOINT a; ... SAVEPOINT b; ...) ROLLBACK TO a çalıştırılırsa b kayıt noktasına ne olur?', 'b de geçersiz olur, çünkü a\'dan sonra tanımlanmıştır', ['b korunur ve hâlâ ona dönülebilir', 'b otomatik olarak COMMIT edilir ve değişiklikleri kalıcı olur', 'b\'ye kadar olan değişiklikler korunur'], 'Bir kayıt noktasına dönmek, ondan sonra tanımlanan bütün kayıt noktalarını da ortadan kaldırır.'),
  ('PostgreSQL\'de CREATE TABLE Ogrenci (...) ile oluşturulan tabloya SELECT * FROM "Ogrenci"; ile erişilmeye çalışılırsa ne olur?', 'Tablo bulunamaz; tırnaksız ad küçük harfe çevrilip \'ogrenci\' olarak saklanmıştır', ['Tablo sorunsuz bulunur', 'Tablonun adı otomatik olarak büyük harfe çevrilir', 'İki ayrı tablo oluşturulmuş olur ve sorgu ikisinin satırlarını birleştirerek okur, çünkü adlar eşleşir'], 'PostgreSQL tırnaksız tanımlayıcıları küçük harfe indirir; çift tırnaklı adlar ise harfi harfine eşleşmelidir.'),
  ('Adlar \'Aslı\', \'Berk\', \'Cansu\' ve \'Bora\' iken WHERE ad BETWEEN \'A\' AND \'C\' kaç ad döndürür?', '3', ['4', '2', '1'], 'Metin karşılaştırmasında \'Cansu\', \'C\' metninden büyüktür ve aralığın dışında kalır; Aslı, Berk ve Bora seçilir.'),
  ('Siparişlerin yalnız yüzde 2\'si \'bekliyor\' durumunda ve sorgular hep bu siparişleri arıyor. PostgreSQL\'de en verimli indeks hangisidir?', 'CREATE INDEX ... ON Siparis (tarih) WHERE durum = \'bekliyor\';', ['CREATE INDEX ... ON Siparis (durum, tarih, musteri_no, tutar);', 'CREATE UNIQUE INDEX ... ON Siparis (durum);', 'CREATE INDEX ... ON Siparis (tutar) WHERE tutar > 0;'], 'Kısmi indeks yalnız koşulu sağlayan satırları içerir; küçük olduğu için hızlıdır ve az yer kaplar.'),
  ('EXPLAIN ANALYZE DELETE FROM Log WHERE yil < 2020; komutunu \'yalnız planı görmek için\' çalıştıran biri neye dikkat etmelidir?', 'Komut gerçekten çalışır ve satırlar silinir', ['Plan hiç gösterilmez', 'Silme işlemi iki kez yapılır', 'Komut yalnız SELECT sorgularında geçerlidir, DELETE için hata verir'], 'EXPLAIN ANALYZE gerçek süreleri ölçmek için ifadeyi yürütür; bu yüzden işlem içinde çalıştırılıp ROLLBACK yapılmalıdır.'),
  ('Satış olmayan günleri de sıfırla gösteren günlük rapor için PostgreSQL\'de hangi yaklaşım kullanılır?', 'generate_series ile tarih listesi üretip satışlarla LEFT JOIN yapmak', ['Satis tablosunu GROUP BY tarih ile gruplamak', 'Satis tablosuna ORDER BY tarih eklemek', 'Satis tablosunda DISTINCT tarih seçip boş günleri raporun sonuna elle eklemek'], 'Satışı olmayan günlerin satırı yoktur; bütün günleri üreten listeyle dış birleştirme bu boşlukları görünür kılar.'),
  ('PostgreSQL\'de bir puan sütununun ortancasını (medyan) hesaplayan ifade hangisidir?', 'PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY puan)', ['AVG(puan) / 2', 'MEDIAN_OF(puan) OVER (ORDER BY puan ROWS UNBOUNDED)', 'MAX(puan) - MIN(puan)'], 'PERCENTILE_CONT sıralı küme fonksiyonudur; 0,5 yüzdelik dilimi ortancaya karşılık gelir.'),
  ('PostgreSQL\'de JSONB türündeki bilgi sütunundan \'sehir\' anahtarının değerini metin olarak alan işleç hangisidir?', 'bilgi ->> \'sehir\'', ['bilgi -> \'sehir\' -> TEXT', 'bilgi.sehir', 'bilgi[\'sehir\'] AS JSON'], '->> işleci JSON değerini metin olarak, -> ise JSON nesnesi olarak döndürür.'),
  ('Milyonlarca satırlık bir listede ileri sayfalara gidildikçe OFFSET yavaşlıyor. Önerilen çözüm hangisidir?', 'Son görülen anahtara göre WHERE id > son_id ORDER BY id LIMIT 20 kullanmak', ['OFFSET değerini artırıp LIMIT\'i azaltmak', 'Sorguya DISTINCT eklemek', 'ORDER BY\'ı kaldırıp sonuçları uygulamada sıralamak ve her sayfada bütün satırları çekmek'], 'OFFSET atlanan satırları da okumak zorundadır; anahtar tabanlı (keyset) sayfalama indeksle doğrudan konuma gider.'),
  ('Bir sinav tablosunda mat, fen ve turkce puanları ayrı sütunlarda tutuluyor. Bunları (ogrenci, ders, puan) satırlarına dönüştürmenin taşınabilir SQL yolu hangisidir?', 'Her ders sütunu için birer SELECT yazıp UNION ALL ile alt alta koymak', ['GROUP BY ogrenci ile SUM almak', 'Tabloyu kendisiyle CROSS JOIN yapmak', 'Sütunları DISTINCT ile birleştirip ORDER BY ders ile sıralamak'], 'Her SELECT bir sütunu satırlara taşır; UNION ALL bunları tek listede toplar (unpivot).'),
  ('PostgreSQL\'de AGE(DATE \'2024-05-10\', DATE \'2000-05-11\') ifadesinin yıl kısmı kaçtır?', '23', ['24', '22', '25'], '11 Mayıs 2024\'e bir gün eksik olduğu için 24. doğum günü henüz gelmemiştir: 23 yıl 11 ay 29 gün.'),
  ('PostgreSQL\'de iki zaman damgası arasındaki farkı saniye cinsinden sayı olarak almak için hangi ifade kullanılır?', 'EXTRACT(EPOCH FROM (bitis - baslangic))', ['EXTRACT(SECOND FROM bitis) - EXTRACT(SECOND FROM baslangic)', 'DATE_TRUNC(\'second\', bitis - baslangic)', '(bitis - baslangic) * 60 * 60 * 24 AS INTEGER'], 'EPOCH alanı bir aralığın toplam saniyesini verir; SECOND alanı ise yalnız 0–59 arasındaki saniye kısmıdır.'),
  ('PostgreSQL\'de TIMESTAMPTZ (TIMESTAMP WITH TIME ZONE) türü değerleri nasıl saklar?', 'UTC\'ye çevirip saklar, okurken oturumun saat dilimine göre gösterir', ['Yazıldığı saat dilimini metin olarak ayrı bir sütunda saklar', 'Hiç dönüşüm yapmadan, yazıldığı andaki yerel saati ve bölge adını birlikte saklar', 'Yalnız tarihi saklar, saati atar'], 'Bu tür, aynı anı farklı saat dilimlerindeki kullanıcılara doğru göstermek için UTC\'ye dayalı tutar.'),
  ('Bayt sırasına göre çalışan \'C\' harmanlamasıyla (collation) ORDER BY ad yapılan bir listede \'Çağla\' ve \'Zeynep\' nasıl sıralanır?', '\'Zeynep\' önce, \'Çağla\' sonra gelir', ['\'Çağla\' önce, \'Zeynep\' sonra gelir', 'İkisi aynı sırayı paylaşır', '\'Çağla\' listeden çıkarılır, çünkü Ç geçersiz sayılır'], 'Ç\'nin kod değeri İngiliz alfabesindeki bütün harflerden büyüktür; Türkçe harmanlamada ise C ile D arasına yerleşir.'),
  ('PostgreSQL\'de bir gruptaki bütün satırlarda onay sütunu TRUE ise TRUE döndüren kümeleme fonksiyonu hangisidir?', 'BOOL_AND', ['BOOL_OR', 'ANY_VALUE', 'COUNT(TRUE)'], 'BOOL_AND (standart adıyla EVERY) mantıksal VE kümelemesidir; BOOL_OR en az bir TRUE arar.'),
  ('Adları alfabetik sırayla virgülle birleştirmek için PostgreSQL\'de STRING_AGG nasıl yazılır?', 'STRING_AGG(ad, \', \' ORDER BY ad)', ['STRING_AGG(ad, \', \') ORDER BY ad', 'ORDER BY STRING_AGG(ad, \', \')', 'STRING_AGG(ORDER BY ad, ad, \', \') WITHIN GROUP'], 'Kümeleme içindeki sıralama fonksiyonun parantezi içinde, son argümandan sonra yazılır.'),
  ('PostgreSQL\'de her müşteri için en son 3 siparişi getirmek amacıyla FROM Musteri m, LATERAL (SELECT ... WHERE s.mno = m.no ORDER BY tarih DESC LIMIT 3) s yazılıyor. LATERAL ne sağlar?', 'FROM\'daki alt sorgunun soldaki tablonun sütunlarına başvurabilmesini', ['Alt sorgunun yalnız bir kez çalışmasını', 'İki tablonun kartezyen çarpımının engellenmesini', 'Alt sorgu sonucunun diske kalıcı yazılmasını ve yeniden kullanılmasını'], 'LATERAL, FROM içindeki alt sorguyu dış satırlara bağımlı (ilişkili) yapar; SQL Server\'daki karşılığı CROSS APPLY\'dır.'),
  ('PostgreSQL\'de iptal edilen siparişlerin kalemlerini Siparis tablosuna bakarak silmek için hangi yazım kullanılır?', 'DELETE FROM Kalem k USING Siparis s WHERE k.sno = s.no AND s.durum = \'iptal\';', ['DELETE Kalem JOIN Siparis WHERE durum = \'iptal\';', 'DELETE FROM Kalem, Siparis WHERE durum = \'iptal\';', 'DELETE FROM Kalem WHERE Siparis.durum = \'iptal\' AND Kalem.sno = Siparis.no ORDER BY sno;'], 'PostgreSQL DELETE ... USING ile başka tabloları birleştirme koşuluna katar; alt sorguyla da yazılabilir.'),
  ('Bir Uye tablosunda aynı e-postayla yinelenen satırlardan yalnız id\'si en küçük olanı bırakmak için PostgreSQL\'de hangi komut kullanılır?', 'DELETE FROM Uye a USING Uye b WHERE a.eposta = b.eposta AND a.id > b.id;', ['DELETE FROM Uye WHERE eposta IN (SELECT eposta FROM Uye);', 'DELETE DISTINCT FROM Uye;', 'DELETE FROM Uye a USING Uye b WHERE a.eposta = b.eposta AND a.id < b.id AND a.eposta IS NOT NULL;'], 'Aynı e-postalı daha küçük id\'li bir eşi bulunan her satır silinir; böylece her e-postanın en küçük id\'li satırı kalır.'),
  ('Bir cihazın durum kayıtlarında (açık, açık, kapalı, kapalı, açık) yalnız durumun değiştiği satırları seçmek için hangi koşul kullanılır?', 'durum IS DISTINCT FROM LAG(durum) OVER (ORDER BY zaman)', ['durum = LAG(durum) OVER (ORDER BY zaman)', 'durum <> FIRST_VALUE(durum) OVER ()', 'durum IN (SELECT DISTINCT durum FROM Kayit GROUP BY durum HAVING COUNT(*) = 1)'], 'Önceki satırdan farklı olan durumlar değişim noktalarıdır; IS DISTINCT FROM ilk satırdaki NULL karşılaştırmasını da doğru işler.'),
  ('Standart SQL\'de A UNION B INTERSECT C ifadesi parantez olmadan nasıl değerlendirilir?', 'A UNION', ['(A UNION B) INTERSECT C', 'Soldan sağa, öncelik gözetmeden', 'Sözdizimi hatası verir; parantez zorunludur'], 'INTERSECT, UNION ve EXCEPT\'ten daha yüksek önceliklidir; karışıklığı önlemek için parantez yazmak önerilir.'),
  ('PostgreSQL\'de birincil anahtarın UUID olarak kendiliğinden üretilmesi için sütun nasıl tanımlanır?', 'id UUID PRIMARY KEY DEFAULT gen_random_uuid()', ['id UUID PRIMARY KEY AUTO_INCREMENT', 'id UUID SERIAL PRIMARY KEY', 'id UUID PRIMARY KEY CHECK (id = gen_random_uuid())'], 'DEFAULT olarak verilen fonksiyon her eklemede yeni bir rastgele UUID üretir.'),
  ('PostgreSQL ile Oracle arasında boş metin (\'\') konusundaki önemli fark nedir?', 'Oracle boş metni NULL sayar, PostgreSQL ayrı bir değer olarak tutar', ['PostgreSQL boş metni NULL sayar, Oracle saymaz', 'İkisi de boş metni kabul etmez', 'İkisi de boş metni tek bir boşluk karakterine çevirir ve öyle saklar'], 'Oracle\'da \'\' IS NULL doğrudur; bu fark taşınan uygulamalarda beklenmedik sonuçlara yol açabilir.'),
];
